// ═══ thenApply — sync transform (like map) ═══
CompletableFuture<String> balanceCF = CompletableFuture.supplyAsync(
    () -> "100000");  // async: fetch balance

CompletableFuture<Integer> parsed = balanceCF
    .thenApply(Integer::parseInt);  // sync transform: String → Integer
// No new async operation — just transforms the result!

// ═══ thenCompose — async chain (like flatMap) ═══
CompletableFuture<String> balanceCF2 = CompletableFuture.supplyAsync(
    () -> "SAV2001");  // async: get account ID

CompletableFuture<Integer> creditScore = balanceCF2
    .thenCompose(accountId -> fetchCreditScoreAsync(accountId));
    // fetchCreditScoreAsync returns CompletableFuture<Integer>
    // thenCompose FLATTENS: CF<CF<Integer>> → CF<Integer>
    // thenApply would give: CF<CF<Integer>> — nested! Wrong!

// ═══ thenCombine — merge two parallel futures ═══
CompletableFuture<Integer> rajeshBalance = CompletableFuture.supplyAsync(
    () -> fetchBalance("SAV2001"));  // async call 1

CompletableFuture<Integer> priyaBalance = CompletableFuture.supplyAsync(
    () -> fetchBalance("CUR3001"));  // async call 2 (runs in PARALLEL!)

CompletableFuture<Integer> total = rajeshBalance
    .thenCombine(priyaBalance, Integer::sum);
    // When BOTH complete: sum them → total!
    // Both fetches run simultaneously — no waiting!

// ═══ FULL PIPELINE EXAMPLE ═══
CompletableFuture<String> result = CompletableFuture
    .supplyAsync(() -> getAccountId("Rajesh"))         // async: get ID
    .thenCompose(id -> fetchBalanceAsync(id))           // async: fetch balance
    .thenApply(balance -> balance.multiply(interestRate)) // sync: calculate
    .thenCombine(fetchTaxRateAsync(), (interest, tax) -> interest.subtract(tax))
    .thenApply(net -> "Net interest: Rs." + net)        // sync: format
    .exceptionally(ex -> "Error: " + ex.getMessage());  // handle errors!

// ═══ ERROR HANDLING ═══
cf.exceptionally(ex -> defaultValue);        // recover from error
cf.handle((result, ex) -> {                  // handle both success + error
    if (ex != null) return "Error";
    return "OK: " + result;
});
cf.whenComplete((result, ex) -> log(result, ex)); // side-effect (no transform)

// ═══ Async variants — run on separate thread ═══
cf.thenApplyAsync(fn);      // fn runs on ForkJoinPool thread
cf.thenApplyAsync(fn, pool); // fn runs on custom pool
// Without Async: fn runs on completing thread (may be caller!)
