package com.bank.cf;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class CompletableFutureTest {

    // ═══ thenApply — sync transform ═══
    @Test
    void thenApply_syncTransform() throws Exception {
        String result = CompletableFuture
            .supplyAsync(() -> "50000")
            .thenApply(Integer::parseInt)
            .thenApply(balance -> balance * 2)
            .thenApply(doubled -> "Balance doubled: " + doubled)
            .get();

        assertThat(result).isEqualTo("Balance doubled: 100000");
    }

    // ═══ thenCompose — async chain (flatMap) ═══
    @Test
    void thenCompose_asyncChain() throws Exception {
        CompletableFuture<String> result = CompletableFuture
            .supplyAsync(() -> "SAV2001")
            .thenCompose(id -> CompletableFuture.supplyAsync(
                () -> "Balance for " + id + ": 100000"));

        assertThat(result.get()).isEqualTo("Balance for SAV2001: 100000");
    }

    // ═══ thenCombine — merge two parallel futures ═══
    @Test
    void thenCombine_parallelMerge() throws Exception {
        CompletableFuture<Integer> rajesh = CompletableFuture.supplyAsync(() -> {
            sleep(100); return 100000;
        });
        CompletableFuture<Integer> priya = CompletableFuture.supplyAsync(() -> {
            sleep(100); return 250000;
        });

        long start = System.currentTimeMillis();
        Integer total = rajesh.thenCombine(priya, Integer::sum).get();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(total).isEqualTo(350000);
        assertThat(elapsed).isLessThan(300);  // parallel: ~100ms, not 200ms!
    }

    // ═══ exceptionally — error recovery ═══
    @Test
    void exceptionally_errorRecovery() throws Exception {
        String result = CompletableFuture
            .supplyAsync(() -> { throw new RuntimeException("DB down!"); })
            .exceptionally(ex -> "Fallback: cache value")
            .thenApply(val -> "Result: " + val)
            .get();

        assertThat(result).isEqualTo("Result: Fallback: cache value");
    }

    // ═══ Full loan approval pipeline ═══
    @Test
    void loanApprovalPipeline() throws Exception {
        CompletableFuture<String> decision = CompletableFuture
            .supplyAsync(() -> "CUST-001")                         // get customer
            .thenCompose(id -> CompletableFuture.supplyAsync(      // fetch credit score
                () -> { sleep(100); return 750; }))
            .thenCombine(
                CompletableFuture.supplyAsync(() -> {              // fetch property value (parallel!)
                    sleep(100); return new BigDecimal("5000000");
                }),
                (score, property) -> score >= 700 && property.compareTo(new BigDecimal("1000000")) > 0
                    ? "APPROVED" : "REJECTED"
            );

        assertThat(decision.get(5, TimeUnit.SECONDS)).isEqualTo("APPROVED");
    }

    private void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { }
    }
}
